-- Secret store (owner, 2026-11-14): secrets (e.g. the agent's long-lived token) are AES-256-GCM
-- encrypted files under <WORK_HUB_DATA_DIR>/secrets/; their key lives here, generated by the server
-- on first start. A copy of the data dir alone or a dump of the database alone reveals nothing.
CREATE TABLE IF NOT EXISTS secret_key (
    id smallint PRIMARY KEY CHECK (id = 1),
    key bytea NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE secret_key IS 'The one key of the secret store: encrypts the files under <data dir>/secrets/ (AES-256-GCM).';
COMMENT ON COLUMN secret_key.id IS 'Always 1 (one key).';
COMMENT ON COLUMN secret_key.key IS '32 random bytes generated by the server on first start. Losing it only means users log in to their agent again.';
COMMENT ON COLUMN secret_key.created_at IS 'When the key was generated.';
